  h1, h2, h3, h4, p, span, td, th, label {
    overflow-wrap: break-word;
    word-break: break-word;
  }

  /* All tables scroll horizontally */
  .overflow-x-auto {
    -webkit-overflow-scrolling: touch;
  }

  /* Reduce font size on mobile for table content */
  table {
    font-size: 0.75rem;
